import{_ as e,o as r,c as l,am as t}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"第三版_营销项目","description":"","frontmatter":{"title":"第三版_营销项目","excerpt":"摘要","date":"2026-11-07 19:42:57","updated":"2026-11-07 19:42:57"},"headers":[],"relativePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_面试速刷版_第二版/第三版_营销项目.md","filePath":"面试准备/面试煎熬成蛋/面试煎熬成蛋_面试速刷版_第二版/第三版_营销项目.md","lastUpdated":null}'),i={name:"面试准备/面试煎熬成蛋/面试煎熬成蛋_面试速刷版_第二版/第三版_营销项目.md"};function o(h,a,s,n,d,c){return r(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="项目方面-最近一个项目" tabindex="-1">项目方面 - 最近一个项目 <a class="header-anchor" href="#项目方面-最近一个项目" aria-label="Permalink to &quot;项目方面 - 最近一个项目&quot;">​</a></h3><p>项目概述：本平台面向公司内部业务人员及外部供应商，致力于将线下营销活动流程全面线上化。核心涵盖活动管理（AOC 活动、MRS 店铺活动、趋势跟卖活动等）、规则维护、价格体系、供应商报名及店铺运营等模块。实现从商品中台下发的商品拆分、活动下发、自营/供应商报名到预算分配的全链路闭环，大幅降低人工干预与运营成本。</p><p>技术栈：Spring Boot + MySQL + Redis + Elasticsearch + Kafka + XXL-Job + SpringEvent 等。</p><p>职责：</p><ol><li>活动异动流程优化：针对高频活动异动场景，重构处理流程，采用分批消费、小步快跑的异步控制策略，有效平抑系统流量峰值，提升系统吞吐量与稳定性，处理耗时从42小时缩短到 8 小时；</li><li>活动体系架构重构： 25 年活动体系改造，运用策略模式、模板方法模式对活动核心链路进行抽象。沉淀统一标准模板以支撑 AOC 活动、MRS 店铺活动及趋势跟卖等不同策略的实现，极大提升了代码复用性与后续迭代效率，新活动类型同流程接入从15 天缩短到平均 6天。</li><li>SKC 商品公共属性抽离与 ES 查询优化：抽离商品 SKC 公共属性（店铺 ID、商品层次、标签等），构建独立 SKC 表。将公共属性及变更监听统一汇入 ES 大索引集合，针对不同活动 ID 和类型，采用 ES 子集合字段（嵌套文档）精准控制查询范围。同时，实现同一套监听机制下的精准字段级增量更新，大幅降低 ES 写入压力并提升查询性能。</li><li>扣款单生成判定链路接入：负责订单接入后的扣款判定链路，按「解析订单报文 → 提取订单号 → 查询 SKC 商品信息 → 取出库时间 → 判定是否命中自营店铺活动 → 输出扣款结论」处理 AOC 等多类活动，覆盖订单缺失 SKC、出库时间跨活动周期、活动已下线等异常分支。</li><li>营销工作台：选品圈品与补贴测算：把选品、圈品、规则配置到下发报名全流程线上化，支持多规则叠加圈选与下发前模拟预演（先算不落库），并按目标利润反推采购价降幅、测算补贴额，结果写入 SR 表供数仓加工。</li><li>活动复盘模块：按业务视角（部门 / 店铺 / 活动类型）聚合活动结束后的销量、UV、点击量等指标，负责指标口径与数仓的对齐和校验后落地。</li><li>大商品列表性能优化：针对大体量商品列表查询场景，引入线程池 + CompletableFuture 进行并发查询与数据聚合，显著缩短接口响应时间（RT）。</li></ol><hr><p>每个问题按这 6 行准备：</p><ul><li><strong>背景</strong>：为什么做</li><li><strong>方案</strong>：核心设计</li><li><strong>细节</strong>：关键表/消息/ES DSL/线程池参数</li><li><strong>异常</strong>：重复、失败、延迟、乱序、补偿</li><li><strong>指标</strong>：QPS、RT、积压、写入量、失败率、人工减少</li><li><strong>权衡</strong>：为什么不用另一个方案，如果重做怎么改</li></ul><p>优先准备 <strong>P0：项目整体链路、活动异动、活动体系重构、SKC+ES、扣款幂等/事务、大列表线程池</strong> 这 6 块。</p><h3 id="vibe-coding" tabindex="-1">Vibe Coding <a class="header-anchor" href="#vibe-coding" aria-label="Permalink to &quot;Vibe Coding&quot;">​</a></h3><h4 id="你们怎么使用-claude-code-提效的-具体怎么做的" tabindex="-1">你们怎么使用 claude code 提效的，具体怎么做的 <a class="header-anchor" href="#你们怎么使用-claude-code-提效的-具体怎么做的" aria-label="Permalink to &quot;你们怎么使用 claude code 提效的，具体怎么做的&quot;">​</a></h4><p>其实我们在去年的时候，还是使用 github Copilot 进行代码补全，</p><p>今年的时候由于 claude code 火爆起来，我们就开始转向了使用 cc；</p><p>当时我们主要使用的思路有三种：一种是自己搭建一个产品文档平台，通过一开始就对接产品文档，产品在这个平台进行维护，开发接手后，其实相当于技术文档了。半技术文档这种。这个产品的优势其实并不好，但是当时的时候还没有 skills 之类的，维护好产品文档后，就直接让代码生成。</p><p>第二种是我们维护了从需求文档分析流程到开发流程、代码审查流程、单元测试自动生成流程、测试流程，通过项目统一的 skills 去维护一套比较合规的开发流程落地，并让项目跑起来。</p><p>第三种是我们维护了一个知识库平台，就类似向量数据库这种，不过实际测试下来，还是RAG文档+代码分析这种方式效果会更好一些。</p><p>后面我们还是放弃了统一的skills，除了最开始统一的单元测试生成 skills 和 代码审查 skills 效果使用频率很好，其他都有点个性化操作，会根据公共提供的 skills 去跑对应的开发提效。</p><p>我觉得这些东西的本质还是为了开发提效，项目上目前还是倾向于统一的skills管理和技术文档先行，我个人实际开发经验下来，最好还是要自己的部分改造skills，以及一些经常遇到的场景落地为自己的skills，并且保持更新，如果发现效果的确不行，早点放弃维护和放弃。还有使用比较多的是一些查询日志和数据库，可能在某一个需求的开发过程中，如何进行这个效果的评估，其实还是挺关键的。</p><p>另外一个很大的提效就是前端的内容，目前个人做的还是一些小需求进行个人开发，大的需求还是会由前端人员介入。</p><h3 id="业务" tabindex="-1">业务 <a class="header-anchor" href="#业务" aria-label="Permalink to &quot;业务&quot;">​</a></h3><h4 id="这个平台解决的核心业务痛点是什么-线上化前后流程差异在哪" tabindex="-1">这个平台解决的核心业务痛点是什么？线上化前后流程差异在哪？ <a class="header-anchor" href="#这个平台解决的核心业务痛点是什么-线上化前后流程差异在哪" aria-label="Permalink to &quot;这个平台解决的核心业务痛点是什么？线上化前后流程差异在哪？&quot;">​</a></h4><p>电商的商品，其实在新建款的时候，会绑定对应的供应商ID和店铺ID，这个项目其实是针对专门的自营店铺的款，进行单独管理和处理。提供供应商报名入口，他的盈利模式，是通过供应商进行报名，会提供采购价和编辑采购价降幅；</p><p>报名入口的上游的商品中台，可以理解是商品的前端界面入口，不过这个是另外是另外一个系统的业务边界，我们业务内部是称为供货价。我们这一套玩法，其实就是基于采购价、成本价和供货价，之间的差额做一些业务上的动作。</p><p>而只要产生实际订单，我们会判断是否真的参加过我们系统的活动，如果判断已经参加且生效，则会进行定时任务扣款发起操作，生成扣款单和扣款明细。</p><p>我们针对活动业务，其实有比如 白名单活动下发、规则下发、活动报名、智能测算、报名平台等操作。</p><p>线上化流程在于就是提供了一个是系统级别的入口，方便和其他系统联动，能做的业务其实还挺多的，不过业务边界还是限定在自营店铺商品这个圈品池内。</p><h4 id="内部业务人员和外部供应商分别怎么使用-权限和入口怎么隔离" tabindex="-1">内部业务人员和外部供应商分别怎么使用？权限和入口怎么隔离？ <a class="header-anchor" href="#内部业务人员和外部供应商分别怎么使用-权限和入口怎么隔离" aria-label="Permalink to &quot;内部业务人员和外部供应商分别怎么使用？权限和入口怎么隔离？&quot;">​</a></h4><p>我们区分了两个入口，内部使用工号，外部使用供应商ID。在方法层面上，能操作的动作其实就不一样。</p><h4 id="系统日均活动量、商品量、供应商数、qps、峰值流量大概多少" tabindex="-1">系统日均活动量、商品量、供应商数、QPS、峰值流量大概多少？ <a class="header-anchor" href="#系统日均活动量、商品量、供应商数、qps、峰值流量大概多少" aria-label="Permalink to &quot;系统日均活动量、商品量、供应商数、QPS、峰值流量大概多少？&quot;">​</a></h4><p>我们一般单个活动有 100 - 200左右的商品数量，每一天都活动大概是 1 - 5 个左右。不过有时候也是有一些小活动，可能只有几万的商品这种。</p><p>供应商数量不一定，看实际对应的店铺下的供应商ID数量。</p><p>QPS，外部访问接口，我们有提供外部库存接口和查询活动等接口，这种外部接口的访问频率是最高的，不过也大概在100 QPS 范围内。峰值就是100.</p><h4 id="你负责的模块在链路中的位置-上下游系统有哪些" tabindex="-1">你负责的模块在链路中的位置？上下游系统有哪些？ <a class="header-anchor" href="#你负责的模块在链路中的位置-上下游系统有哪些" aria-label="Permalink to &quot;你负责的模块在链路中的位置？上下游系统有哪些？&quot;">​</a></h4><p>我主要负责 活动异动、活动报名 的流程，上游的系统主要有数仓、商品中台、价格PCC等系统，下游主要有MRS、WMS、MES等。</p><h3 id="合作" tabindex="-1">合作 <a class="header-anchor" href="#合作" aria-label="Permalink to &quot;合作&quot;">​</a></h3><h4 id="你和你同事的分工是怎么做的" tabindex="-1">你和你同事的分工是怎么做的 <a class="header-anchor" href="#你和你同事的分工是怎么做的" aria-label="Permalink to &quot;你和你同事的分工是怎么做的&quot;">​</a></h4><p>我主要负责活动异动链路和活动报名链路，还有两个同事，分别负责扣款流程和价格体系，以及店铺运营。</p><h3 id="技术难点" tabindex="-1">技术难点 <a class="header-anchor" href="#技术难点" aria-label="Permalink to &quot;技术难点&quot;">​</a></h3><h4 id="项目最大的技术难点是什么-你个人最大的贡献是什么" tabindex="-1">项目最大的技术难点是什么？你个人最大的贡献是什么？ <a class="header-anchor" href="#项目最大的技术难点是什么-你个人最大的贡献是什么" aria-label="Permalink to &quot;项目最大的技术难点是什么？你个人最大的贡献是什么？&quot;">​</a></h4><p>最大的技术难点，目前是活动异动流程的优化，我们一般最开始为了快速搭建这个项目，采用了挺多串行链路，最开始也使用了部分MQ进行异步操作，不过维度粒度比较大，是直接到单个活动维度，一个活动从下发到真正落表的流程可能要一天多。</p><p>接手后，最开始做的方式还是先定位耗时步骤，先记录日志，将每一步的耗时打印，收集一周左右的日志耗时后，开始写方案动手。</p><p>第一版方案是 将商品的数量通过MQ拆分，比如一个平台商品200W拆分10000一批，使用 redis 写计数器，只有计数器 到 0 的时候，判断这一步算最后阶段，才进入下一个步骤。</p><p>这里其实还是有衡量，是MQ 的并行度设置和 分批数量，并行度高会导致MySQL 的CPU飙升，折中还是取了2，分批数量使用 apollo 数量控制，最后慢慢发现设置到 1000 反而是一个很好的数量，这个也是慢慢的通过监控耗时日志获取的。</p><p>后面随着 skills 的流行，公司架构组也有通用的 skills，不过一般是线上的 skills ，我做类似的工作也是先封装好自己的 skills，然后再调用查询日志或者数据库的数据，出一个大概报告，这个工作减轻了我很多的工作量。</p><p>类似的一个思路吧，通过这种方式慢慢优化，将耗时最后控制到了 8 小时左右，符合业务预期，效果提升也比较明显。</p><p>第二个技术难点，就是将活动报名的流程通过策略的方式接耦，我们当时其实已经有多个活动在跑了。整体思路是想定时这一套活动流程，后续活动流程都能接入。</p><h3 id="经历" tabindex="-1">经历 <a class="header-anchor" href="#经历" aria-label="Permalink to &quot;经历&quot;">​</a></h3><h4 id="有没有线上故障-怎么发现、止损、复盘、改进" tabindex="-1">有没有线上故障？怎么发现、止损、复盘、改进？ <a class="header-anchor" href="#有没有线上故障-怎么发现、止损、复盘、改进" aria-label="Permalink to &quot;有没有线上故障？怎么发现、止损、复盘、改进？&quot;">​</a></h4><h3 id="活动异动流程" tabindex="-1">活动异动流程 <a class="header-anchor" href="#活动异动流程" aria-label="Permalink to &quot;活动异动流程&quot;">​</a></h3><h4 id="重构前流程是什么-瓶颈在数据库、接口、mq-还是下游" tabindex="-1">重构前流程是什么？瓶颈在数据库、接口、MQ 还是下游？ <a class="header-anchor" href="#重构前流程是什么-瓶颈在数据库、接口、mq-还是下游" aria-label="Permalink to &quot;重构前流程是什么？瓶颈在数据库、接口、MQ 还是下游？&quot;">​</a></h4><p>在外围数据接口的调用时间，在整个服务商品数据量很多。</p><h4 id="分批消费、小步快跑-怎么分批-按活动-id、商品-id、时间窗还是游标-批大小怎么定-压测依据是什么" tabindex="-1">“分批消费、小步快跑”怎么分批？按活动 ID、商品 ID、时间窗还是游标？批大小怎么定？压测依据是什么？ <a class="header-anchor" href="#分批消费、小步快跑-怎么分批-按活动-id、商品-id、时间窗还是游标-批大小怎么定-压测依据是什么" aria-label="Permalink to &quot;“分批消费、小步快跑”怎么分批？按活动 ID、商品 ID、时间窗还是游标？批大小怎么定？压测依据是什么？&quot;">​</a></h4><p>根据商品，每一批1000这种。</p><p>批大小，是设置了动态配置，根据线上数据慢慢调整的，压测就是看实际的数据库CPU指标，以及看日志每一个步骤的耗时。</p><h4 id="活动异动处理从-42-小时降到-8-小时-请讲一下这次优化的完整过程-原来为什么这么慢、瓶颈在哪个环节-分批消费的批大小和-小步快跑-的节奏怎么定-异步之后如何保证异动不丢、不重、不乱序" tabindex="-1"><strong>活动异动处理从 42 小时降到 8 小时</strong>,  请讲一下这次优化的完整过程：原来为什么这么慢、瓶颈在哪个环节，分批消费的批大小和“小步快跑”的节奏怎么定，异步之后如何保证异动不丢、不重、不乱序？ <a class="header-anchor" href="#活动异动处理从-42-小时降到-8-小时-请讲一下这次优化的完整过程-原来为什么这么慢、瓶颈在哪个环节-分批消费的批大小和-小步快跑-的节奏怎么定-异步之后如何保证异动不丢、不重、不乱序" aria-label="Permalink to &quot;**活动异动处理从 42 小时降到 8 小时**,  请讲一下这次优化的完整过程：原来为什么这么慢、瓶颈在哪个环节，分批消费的批大小和“小步快跑”的节奏怎么定，异步之后如何保证异动不丢、不重、不乱序？&quot;">​</a></h4><h4 id="异步控制策略具体怎么实现-kafka-消费-线程池-限流" tabindex="-1">异步控制策略具体怎么实现？Kafka 消费 + 线程池 + 限流？ <a class="header-anchor" href="#异步控制策略具体怎么实现-kafka-消费-线程池-限流" aria-label="Permalink to &quot;异步控制策略具体怎么实现？Kafka 消费 + 线程池 + 限流？&quot;">​</a></h4><p>Kafka 消费</p><h4 id="如何平抑峰值-有没有削峰、限流、降级、背压-异动过程中部分成功怎么办-补偿任务怎么做-xxl-job-怎么参与" tabindex="-1">如何平抑峰值？有没有削峰、限流、降级、背压？异动过程中部分成功怎么办？补偿任务怎么做？XXL-Job 怎么参与？ <a class="header-anchor" href="#如何平抑峰值-有没有削峰、限流、降级、背压-异动过程中部分成功怎么办-补偿任务怎么做-xxl-job-怎么参与" aria-label="Permalink to &quot;如何平抑峰值？有没有削峰、限流、降级、背压？异动过程中部分成功怎么办？补偿任务怎么做？XXL-Job 怎么参与？&quot;">​</a></h4><p>产生堆积的情况，其实还是有的，不过我们一般都是直接看消费接口是否正常</p><p>补偿我在写的时候就写了定时任务补充，可以根据整个活动维度或者消息体的内容进行重试，因为这个流程是可以不做幂等的，直接触发定时任务就行。</p><h4 id="消息堆积怎么处理的" tabindex="-1">消息堆积怎么处理的？ <a class="header-anchor" href="#消息堆积怎么处理的" aria-label="Permalink to &quot;消息堆积怎么处理的？&quot;">​</a></h4><h4 id="如果让你再优化-下一步会做什么" tabindex="-1">如果让你再优化，下一步会做什么？ <a class="header-anchor" href="#如果让你再优化-下一步会做什么" aria-label="Permalink to &quot;如果让你再优化，下一步会做什么？&quot;">​</a></h4><h3 id="策略-模板方法" tabindex="-1">策略/模板方法 <a class="header-anchor" href="#策略-模板方法" aria-label="Permalink to &quot;策略/模板方法&quot;">​</a></h3><h4 id="_25-年活动体系改造前有什么问题-代码重复、扩展难还是业务规则混乱" tabindex="-1">25 年活动体系改造前有什么问题？代码重复、扩展难还是业务规则混乱？ <a class="header-anchor" href="#_25-年活动体系改造前有什么问题-代码重复、扩展难还是业务规则混乱" aria-label="Permalink to &quot;25 年活动体系改造前有什么问题？代码重复、扩展难还是业务规则混乱？&quot;">​</a></h4><p>主要是业务耦合程度高，还有就是不好拿出去讲我们系统是怎么做的，解耦之后，我们可以在领导会议上，讲述整个活动链路，目前按照活动下发、供应商活动报名、商品审核、商品提报、取消报名等统一流程。</p><p>新增活动类型，也按照类似一套主抽象流程去处理，同时表数据也可以考虑是否复用。</p><h4 id="你怎么抽象的-做了哪些动作-和之前比-具体提效体现在什么地方。-新活动类型-15-天缩短到-6-天-这个数字是怎么算出来的" tabindex="-1">你怎么抽象的？做了哪些动作？和之前比，具体提效体现在什么地方。“新活动类型 15 天缩短到 6 天”这个数字是怎么算出来的？ <a class="header-anchor" href="#你怎么抽象的-做了哪些动作-和之前比-具体提效体现在什么地方。-新活动类型-15-天缩短到-6-天-这个数字是怎么算出来的" aria-label="Permalink to &quot;你怎么抽象的？做了哪些动作？和之前比，具体提效体现在什么地方。“新活动类型 15 天缩短到 6 天”这个数字是怎么算出来的？&quot;">​</a></h4><p>先说一下我们整体项目架构是DDD的方式，因此主要这一套改造是在聚合层进行的。</p><h3 id="skc-公共属性抽离与-es-查询优化" tabindex="-1">SKC 公共属性抽离与 ES 查询优化 <a class="header-anchor" href="#skc-公共属性抽离与-es-查询优化" aria-label="Permalink to &quot;SKC 公共属性抽离与 ES 查询优化&quot;">​</a></h3><h4 id="先说一下当前的业务背景和具体怎么做的。" tabindex="-1">先说一下当前的业务背景和具体怎么做的。 <a class="header-anchor" href="#先说一下当前的业务背景和具体怎么做的。" aria-label="Permalink to &quot;先说一下当前的业务背景和具体怎么做的。&quot;">​</a></h4><h4 id="mysql-和-es-不一致怎么办" tabindex="-1">MySQL 和 ES 不一致怎么办？ <a class="header-anchor" href="#mysql-和-es-不一致怎么办" aria-label="Permalink to &quot;MySQL 和 ES 不一致怎么办？&quot;">​</a></h4><h4 id="es-嵌套文档-字段级增量更新为什么选-nested-而不是宽表或-join-nested-的查询和更新代价你清楚吗-字段级增量更新-具体怎么实现的-一次监听更新一条还是批量更新-更新时怎么避免整文档-rewrite、怎么防止并发覆盖" tabindex="-1"><strong>ES 嵌套文档 + 字段级增量更新</strong>为什么选 nested 而不是宽表或 join，nested 的查询和更新代价你清楚吗？“字段级增量更新”具体怎么实现的，一次监听更新一条还是批量更新，更新时怎么避免整文档 rewrite、怎么防止并发覆盖？ <a class="header-anchor" href="#es-嵌套文档-字段级增量更新为什么选-nested-而不是宽表或-join-nested-的查询和更新代价你清楚吗-字段级增量更新-具体怎么实现的-一次监听更新一条还是批量更新-更新时怎么避免整文档-rewrite、怎么防止并发覆盖" aria-label="Permalink to &quot;**ES 嵌套文档 + 字段级增量更新**为什么选 nested 而不是宽表或 join，nested 的查询和更新代价你清楚吗？“字段级增量更新”具体怎么实现的，一次监听更新一条还是批量更新，更新时怎么避免整文档 rewrite、怎么防止并发覆盖？&quot;">​</a></h4><h3 id="扣款单生成判定链路接入" tabindex="-1">扣款单生成判定链路接入 <a class="header-anchor" href="#扣款单生成判定链路接入" aria-label="Permalink to &quot;扣款单生成判定链路接入&quot;">​</a></h3><h4 id="扣款单生成判定链路-请把-解析订单报文-→-提取订单号-→-查-skc-→-取出库时间-→-判定命中店铺活动-→-出结论-这条链讲清楚-中间哪一步可能拿到脏数据-跨活动周期、订单缺失-skc、活动已下线这几个分支分别怎么处理" tabindex="-1"><strong>扣款单生成判定链路</strong> 请把“解析订单报文 → 提取订单号 → 查 SKC → 取出库时间 → 判定命中店铺活动 → 出结论”这条链讲清楚，中间哪一步可能拿到脏数据？跨活动周期、订单缺失 SKC、活动已下线这几个分支分别怎么处理？ <a class="header-anchor" href="#扣款单生成判定链路-请把-解析订单报文-→-提取订单号-→-查-skc-→-取出库时间-→-判定命中店铺活动-→-出结论-这条链讲清楚-中间哪一步可能拿到脏数据-跨活动周期、订单缺失-skc、活动已下线这几个分支分别怎么处理" aria-label="Permalink to &quot;**扣款单生成判定链路** 请把“解析订单报文 → 提取订单号 → 查 SKC → 取出库时间 → 判定命中店铺活动 → 出结论”这条链讲清楚，中间哪一步可能拿到脏数据？跨活动周期、订单缺失 SKC、活动已下线这几个分支分别怎么处理？&quot;">​</a></h4><h3 id="营销工作台" tabindex="-1">营销工作台 <a class="header-anchor" href="#营销工作台" aria-label="Permalink to &quot;营销工作台&quot;">​</a></h3><h3 id="大商品列表性能优化" tabindex="-1">大商品列表性能优化 <a class="header-anchor" href="#大商品列表性能优化" aria-label="Permalink to &quot;大商品列表性能优化&quot;">​</a></h3><h4 id="线程池-completablefuture-优化大商品列表-几个任务并行、用的哪个线程池、为什么要单独隔离一个池-任务超时或某个子查询抛异常时整体怎么降级-会不会把-tomcat-线程耗尽" tabindex="-1"><strong>线程池 + CompletableFuture 优化大商品列表</strong> 几个任务并行、用的哪个线程池、为什么要单独隔离一个池？任务超时或某个子查询抛异常时整体怎么降级，会不会把 Tomcat 线程耗尽？ <a class="header-anchor" href="#线程池-completablefuture-优化大商品列表-几个任务并行、用的哪个线程池、为什么要单独隔离一个池-任务超时或某个子查询抛异常时整体怎么降级-会不会把-tomcat-线程耗尽" aria-label="Permalink to &quot;**线程池 + CompletableFuture 优化大商品列表** 几个任务并行、用的哪个线程池、为什么要单独隔离一个池？任务超时或某个子查询抛异常时整体怎么降级，会不会把 Tomcat 线程耗尽？&quot;">​</a></h4>',77)])])}const b=e(i,[["render",o]]);export{u as __pageData,b as default};
